-- Data dictionary in DDL: type, required (NOT NULL), allowed values (ENUM), unit/validation (COMMENT), uniqueness (PK/UNIQUE), cardinality (FK).
CREATE TABLE facility(facility_id VARCHAR(8) PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,site_type ENUM('WATER_TREATMENT','PROCESS_UTILITY','DISTRICT_COOLING') NOT NULL,timezone VARCHAR(40) NOT NULL,status ENUM('ACTIVE','DECOMMISSIONED') NOT NULL,commissioned_on DATE NOT NULL);
CREATE TABLE tank(tank_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,capacity_m3 INT NOT NULL COMMENT 'm3, >0',min_level_pct INT NOT NULL COMMENT '%',max_level_pct INT NOT NULL COMMENT '%',fluid VARCHAR(20) NOT NULL,status ENUM('IN_SERVICE','OUT_OF_SERVICE') NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id));
CREATE TABLE pump(pump_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,src_tank_id VARCHAR(10) NOT NULL,dest_tank_id VARCHAR(10) NOT NULL,q_nom_m3h DOUBLE NOT NULL COMMENT 'm3/h nominal flow',shutoff_head_bar DOUBLE NOT NULL COMMENT 'bar at zero flow',rated_kw DOUBLE NOT NULL COMMENT 'kW',status ENUM('RUNNING','STANDBY','FAULT') NOT NULL,installed_on DATE NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id),FOREIGN KEY(src_tank_id) REFERENCES tank(tank_id),FOREIGN KEY(dest_tank_id) REFERENCES tank(tank_id));
CREATE TABLE valve(valve_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,valve_type ENUM('GATE','BALL','CHECK') NOT NULL,role ENUM('ISOLATION','SUCTION','DISCHARGE') NOT NULL,state ENUM('OPEN','THROTTLED','CLOSED') NOT NULL,open_pct INT NOT NULL COMMENT '% open 0-100',installed_on DATE NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id));
CREATE TABLE pipe(pipe_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,serves_pump_id VARCHAR(10) NULL,seq INT NULL COMMENT 'order along the pump line',from_node_id VARCHAR(10) NOT NULL COMMENT 'TANK/VALVE/PUMP id (polymorphic; generator validates, edge cases deliberate)',to_node_id VARCHAR(10) NOT NULL,diameter_mm INT NOT NULL COMMENT 'mm',length_m INT NOT NULL COMMENT 'm',status ENUM('IN_SERVICE','OUT_OF_SERVICE') NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id));
CREATE TABLE pump_valve(pump_id VARCHAR(10) NOT NULL,valve_id VARCHAR(10) NOT NULL,role VARCHAR(12) NOT NULL,effective_from DATE NOT NULL,effective_to DATE NULL,PRIMARY KEY(pump_id,valve_id,effective_from),FOREIGN KEY(pump_id) REFERENCES pump(pump_id),FOREIGN KEY(valve_id) REFERENCES valve(valve_id));
CREATE TABLE sensor(sensor_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,asset_type ENUM('PUMP','TANK') NOT NULL,asset_id VARCHAR(10) NOT NULL,pump_id VARCHAR(10) NULL,measurand ENUM('FLOW','PRESSURE','INLET_FLOW','LEVEL') NOT NULL,unit VARCHAR(8) NOT NULL,range_min DOUBLE NOT NULL,range_max DOUBLE NOT NULL,status VARCHAR(10) NOT NULL,installed_on DATE NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id));
CREATE TABLE telemetry(telemetry_id VARCHAR(10) PRIMARY KEY,sensor_id VARCHAR(10) NOT NULL,ts DATETIME NOT NULL COMMENT '5-minute cadence',value DOUBLE NOT NULL COMMENT 'in sensor.unit',unit VARCHAR(8) NOT NULL,quality ENUM('GOOD','SUSPECT','BAD') NOT NULL,UNIQUE(sensor_id,ts),FOREIGN KEY(sensor_id) REFERENCES sensor(sensor_id));
CREATE TABLE operating_mode(mode_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,mode_name ENUM('NORMAL','HIGH_DEMAND','LOW_DEMAND') NOT NULL,speed_factor DOUBLE NOT NULL,effective_from DATETIME NOT NULL,effective_to DATETIME NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id));
CREATE TABLE alarm(alarm_id VARCHAR(10) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,asset_type VARCHAR(8) NOT NULL,asset_id VARCHAR(10) NOT NULL,pump_id VARCHAR(10) NULL,sensor_id VARCHAR(10) NOT NULL,alarm_type VARCHAR(24) NOT NULL,severity ENUM('WARNING','CRITICAL') NOT NULL,raised_at DATETIME NOT NULL,cleared_at DATETIME NULL COMMENT '>= raised_at',state ENUM('ACTIVE','CLEARED') NOT NULL,alarm_category ENUM('PROCESS','SENSOR') NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id),FOREIGN KEY(sensor_id) REFERENCES sensor(sensor_id));
CREATE TABLE simulation_run(simulation_id VARCHAR(16) PRIMARY KEY,facility_id VARCHAR(8) NOT NULL,pump_id VARCHAR(10) NOT NULL,scenario_type VARCHAR(30) NOT NULL,config_json JSON NULL COMMENT 'NULL only in labelled edge cases',assumptions TEXT NOT NULL,output_json JSON NOT NULL,seed INT NOT NULL,created_at DATETIME NOT NULL,status ENUM('COMPLETED','FAILED') NOT NULL,source ENUM('GENERATOR','API') NOT NULL,FOREIGN KEY(facility_id) REFERENCES facility(facility_id),FOREIGN KEY(pump_id) REFERENCES pump(pump_id));
CREATE TABLE gt_events(scenario_id VARCHAR(10) PRIMARY KEY,issue_type VARCHAR(20) NOT NULL,category ENUM('PROCESS','SENSOR') NOT NULL,facility_id VARCHAR(8) NOT NULL,pump_id VARCHAR(10) NOT NULL,sensor_id VARCHAR(10) NULL,start_ts DATETIME NOT NULL,end_ts DATETIME NOT NULL,severity DOUBLE NOT NULL);
CREATE TABLE gt_edge_cases(case_id VARCHAR(10) PRIMARY KEY,issue_type VARCHAR(40) NOT NULL,table_name VARCHAR(20) NOT NULL,record_id VARCHAR(16) NOT NULL,detail VARCHAR(200));
